begin;
alter table public.saveat_municipalities add column if not exists latitude double precision;
alter table public.saveat_municipalities add column if not exists longitude double precision;
alter table public.saveat_profiles add column if not exists home_municipality_code text references public.saveat_municipalities(code);
alter table public.saveat_profiles add column if not exists radius_km integer not null default 20 check(radius_km between 1 and 200);
alter table public.saveat_profiles add column if not exists vat_number text;
alter table public.saveat_profiles add column if not exists business_address text;

create or replace function public.saveat_save_profile(p_name text,p_type text,p_business text,p_city text,p_radius integer,p_vat text default '',p_address text default '') returns void
language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'Accedi per continuare'; end if;
 if p_radius is null or p_radius not between 1 and 200 then raise exception 'Scegli un raggio tra 1 e 200 km'; end if;
 if not exists(select 1 from public.saveat_municipalities where code=p_city and latitude is not null and longitude is not null) then raise exception 'Seleziona il comune dai suggerimenti'; end if;
 if p_type='business' and (coalesce(p_vat,'') !~ '^[0-9]{11}$' or length(trim(coalesce(p_address,''))) not between 3 and 300) then raise exception 'Indica partita IVA (11 cifre) e indirizzo della sede'; end if;
 perform public.saveat_set_profile(p_name,p_type,p_business);
 update public.saveat_profiles set home_municipality_code=p_city,radius_km=p_radius,vat_number=case when p_type='business' then p_vat else null end,business_address=case when p_type='business' then trim(p_address) else null end where id=auth.uid();
end; $$;
revoke all on function public.saveat_save_profile(text,text,text,text,integer,text,text) from public,anon;
grant execute on function public.saveat_save_profile(text,text,text,text,integer,text,text) to authenticated;

create or replace function public.saveat_distance_km(a_lat double precision,a_lon double precision,b_lat double precision,b_lon double precision) returns double precision
language sql immutable strict set search_path='' as $$
 select 12742.0*asin(sqrt(least(1.0,greatest(0.0,power(sin(radians(b_lat-a_lat)/2),2)+cos(radians(a_lat))*cos(radians(b_lat))*power(sin(radians(b_lon-a_lon)/2),2)))));
$$;
revoke all on function public.saveat_distance_km(double precision,double precision,double precision,double precision) from public;
grant execute on function public.saveat_distance_km(double precision,double precision,double precision,double precision) to anon,authenticated;

create or replace function public.saveat_search_nearby(p_lat double precision,p_lon double precision,p_radius integer,p_query text default '',p_page integer default 0,p_size integer default 20) returns jsonb
language plpgsql stable security invoker set search_path='' as $$
declare result jsonb;
begin
 if p_lat is null or p_lon is null or p_lat not between -90 and 90 or p_lon not between -180 and 180 or p_radius is null or p_radius not between 1 and 200 then raise exception 'Zona di ricerca non valida'; end if;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.distance_km,q.created_at desc,q.id),'[]'::jsonb) into result from (
 select l.*,public.saveat_distance_km(p_lat,p_lon,m.latitude,m.longitude) distance_km,
 (select coalesce(jsonb_agg(to_jsonb(i) order by i.name),'[]'::jsonb) from public.saveat_items i where i.listing_id=l.id) saveat_items,
 jsonb_build_object('name',m.name,'province',m.province) saveat_municipalities
 from public.saveat_listings l join public.saveat_municipalities m on m.code=l.municipality_code
 where l.status='active' and l.pickup_end>now() and m.latitude is not null and m.longitude is not null
 and public.saveat_distance_km(p_lat,p_lon,m.latitude,m.longitude)<=p_radius
 and exists(select 1 from public.saveat_items i where i.listing_id=l.id and i.available>0)
 and (coalesce(trim(p_query),'')='' or l.title ilike '%'||left(p_query,100)||'%' or exists(select 1 from public.saveat_items i where i.listing_id=l.id and i.name ilike '%'||left(p_query,100)||'%'))
 order by distance_km,l.created_at desc,l.id limit least(greatest(coalesce(p_size,20),1),50) offset greatest(coalesce(p_page,0),0)*least(greatest(coalesce(p_size,20),1),50)
 ) q;
 return result;
end; $$;
revoke all on function public.saveat_search_nearby(double precision,double precision,integer,text,integer,integer) from public;
grant execute on function public.saveat_search_nearby(double precision,double precision,integer,text,integer,integer) to anon,authenticated;

